function openDecision(aid,stage,verdict){decisionBulk=false;const a=snapshot.articles.find(a=>a.id===aid),f=$('#decisionForm');f.reset();f.elements.article_id.value=aid;f.elements.stage.value=stage;f.elements.verdict.value=verdict;$('#decisionTitle').textContent=verdictLabels[verdict]+' · '+(stage==='title_abstract'?'título/resumo':'texto completo');$('#decisionArticle').textContent=a.metadata_json.title;if(a.recommendation.recommendation===verdict)f.elements.reason.value='Concordo com a recomendação após revisar os critérios: '+a.recommendation.reason;$('#decisionDialog').showModal();}
