async function download(path,name,open=false){const r=await api(path),url=URL.createObjectURL(await r.blob());if(open){const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener';a.click();}else{const a=document.createElement('a');a.href=url;a.download=name;a.click();}setTimeout(()=>URL.revokeObjectURL(url),60000);}
