let prismaUrl='';async function renderPrisma(){if(!snapshot||tab!=='delivery')return;const r=await api(`/reviews/${rid}/export/svg`);if(prismaUrl)URL.revokeObjectURL(prismaUrl);prismaUrl=URL.createObjectURL(await r.blob());$('#prismaPreview').innerHTML=`<img src="${prismaUrl}" alt="Fluxo PRISMA da pesquisa com as contagens e pendências atuais">`;}
function renderDelivery(){const d=decisionsMap(),included=snapshot.articles.filter(a=>d[a.id+':title_abstract']?.verdict==='include');$('#pdfAvailability').innerHTML=included.length?included.map(a=>`<div class="availability-row"><div><strong>${esc(a.metadata_json.title)}</strong><p>${a.pdf.status==='available'?'✓ PDF legal disponível · '+(a.pdf.pages||'')+' páginas':esc(a.pdf.reason||'Recuperação ainda não concluída')}</p>${a.pdf.status!=='available'?`<a href="https://pubmed.ncbi.nlm.nih.gov/${encodeURIComponent(a.metadata_json.pmid)}/" target="_blank" rel="noopener noreferrer">Consultar acesso pela plataforma ↗</a>${a.metadata_json.doi?` · <a href="https://doi.org/${encodeURIComponent(a.metadata_json.doi)}" target="_blank" rel="noopener noreferrer">DOI / editora ↗</a>`:''}<label class="fine">Enviar PDF obtido com acesso autorizado<input type="file" accept=".pdf" data-upload-pdf="${a.id}"></label>`:''}</div><span class="pill ${a.pdf.status==='available'?'include':'uncertain'}">${a.pdf.status==='available'?'Disponível':'Pendente'}</span></div>`).join(''):'<p class="muted">Inclua artigos na triagem para iniciar a obtenção dos PDFs.</p>';if(!$('#clickupTask').value)$('#clickupTask').value=snapshot.review.protocol.clickup_task_id||'';const deliveries=snapshot.jobs.filter(j=>j.kind==='drive');const last=deliveries[deliveries.length-1];$('#driveStatus').innerHTML=last?.payload.folder_id?`<a href="https://drive.google.com/drive/folders/${encodeURIComponent(last.payload.folder_id)}" target="_blank" rel="noopener noreferrer">Abrir pasta da pesquisa ↗</a><br>${last.status==='done'?'Entrega concluída.':`${Object.keys(last.payload.completed||{}).length} / ${(last.payload.assets||[]).length} arquivos enviados · ${last.status==='needs_reconciliation'?'conferência necessária':'envio na nuvem'}`}`:last?'Criando a pasta da pesquisa no Drive…':'';}
$('#saveDrive').onclick=e=>action(async()=>{const r=await(await api(`/reviews/${rid}/deliver/drive`,{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()}})).json();message(r.message||'Entrega no Drive solicitada.');await pollReview();startPolling();},e.currentTarget);
