action(async()=>{options=await(await api('/research/options')).json();renderFilters();$('#today').textContent=new Date().toLocaleDateString('pt-BR',{day:'numeric',month:'long',year:'numeric'});const fragment=new URLSearchParams(location.hash.slice(1));if(fragment.has('access_token')){access=fragment.get('access_token');refreshToken=fragment.get('refresh_token')||'';history.replaceState(null,'',location.pathname+location.search);const me=await(await api('/auth/me')).json();if(['invite','recovery'].includes(fragment.get('type'))){$('#login').hidden=true;$('#passwordSetup').hidden=false;$('#accountEmail').textContent='Conta: '+me.email;}else await signed();}const c=await(await api('/config')).json();$('#demo').hidden=!c.demo_mode;if(fragment.has('error_description')){history.replaceState(null,'',location.pathname+location.search);message(fragment.get('error_description'),true);}});

