const workflowNames={draft:'Em preparação',generating:'Gerando prévia',ready_for_review:'Pronta para revisão humana',changes_requested:'Ajustes solicitados',approved:'Prévia aprovada',final_started:'Versão final iniciada',failed:'Falha · verificar Histórico',needs_reconciliation:'Conferência necessária'};
