function plainRich(text){return {type:'doc',content:String(text||'').split('\n').filter(x=>x.trim()).map(line=>({type:line.startsWith('#')?'heading':'paragraph',...(line.startsWith('#')?{attrs:{level:line.startsWith('##')?2:1}}:{}),content:[{type:'text',text:line.replace(/^#{1,6}\s/,'')}]}))};}
function ensureRich(){if(richEditor)return;richEditor=window.createStudioEditor($('#richEditor'),e=>{writingDirty=true;$('#draftContent').value=e.getText();$('#draftSaveStatus').textContent='Alterações não salvas';renderCitations();},(text,from,to)=>{commentSelection=text.slice(0,2000);$('#commentAnchor').textContent=text?'Trecho: '+commentSelection:'Comentário geral';});const commands=[['↶','undo'],['↷','redo'],['Negrito','toggleBold'],['Itálico','toggleItalic'],['Sublinhado','toggleUnderline'],['Riscado','toggleStrike'],['Grifar','toggleHighlight'],['Lista','toggleBulletList'],['Numerar','toggleOrderedList'],['Sobrescrito','toggleSuperscript'],['Subscrito','toggleSubscript']];$('#formatToolbar').innerHTML=commands.map(([label,cmd])=>`<button data-format="${cmd}" title="${label}">${label}</button>`).join('')+`<select id="richHeading" aria-label="Estilo do parágrafo"><option value="0">Texto normal</option><option value="1">Título 1</option><option value="2">Título 2</option><option value="3">Título 3</option></select><select id="richFont" aria-label="Fonte do trecho"><option>Arial</option><option>Times New Roman</option><option>Calibri</option><option>Georgia</option></select><input id="richSize" type="number" value="12" min="8" max="72" aria-label="Tamanho da fonte"><input id="richColor" type="color" value="#203247" aria-label="Cor do texto"><button data-align="left">Esquerda</button><button data-align="center">Centralizar</button><button data-align="right">Direita</button><button data-align="justify">Justificar</button><button id="insertTable">Tabela</button><button id="addRow">＋ Linha</button><button id="addColumn">＋ Coluna</button><button id="deleteTable">Remover tabela</button><button id="editorFind">Localizar</button><button id="editorReplace">Substituir</button><button id="editorComment">Comentar / elogiar</button>`;$$('[data-format]').forEach(b=>b.onclick=()=>richEditor.chain().focus()[b.dataset.format]().run());$$('[data-align]').forEach(b=>b.onclick=()=>richEditor.chain().focus().setTextAlign(b.dataset.align).run());$('#richHeading').onchange=e=>Number(e.target.value)?richEditor.chain().focus().toggleHeading({level:Number(e.target.value)}).run():richEditor.chain().focus().setParagraph().run();$('#richFont').onchange=e=>richEditor.chain().focus().setFontFamily(e.target.value).run();$('#richSize').onchange=e=>richEditor.chain().focus().setFontSize(e.target.value+'pt').run();$('#richColor').onchange=e=>richEditor.chain().focus().setColor(e.target.value).run();$('#insertTable').onclick=()=>richEditor.chain().focus().insertTable({rows:3,cols:3,withHeaderRow:true}).run();$('#addRow').onclick=()=>richEditor.chain().focus().addRowAfter().run();$('#addColumn').onclick=()=>richEditor.chain().focus().addColumnAfter().run();$('#deleteTable').onclick=()=>richEditor.chain().focus().deleteTable().run();$('#editorComment').onclick=()=>$('#commentText').focus();$('#editorFind').onclick=()=>findText(false);$('#editorReplace').onclick=()=>findText(true);}
function findText(replace){const term=prompt('Texto a localizar:');if(!term)return;let match=null;richEditor.state.doc.descendants((n,pos)=>{if(!match&&n.isText){const i=n.text.indexOf(term);if(i>=0)match={from:pos+i,to:pos+i+term.length};}});if(!match){message('Texto não encontrado.');return;}richEditor.chain().focus().setTextSelection(match).run();if(replace){const value=prompt('Substituir por:');if(value!==null)richEditor.chain().focus().insertContent(value.replace(/[<>]/g,'')).run();}}
async function loadPreviewLibrary(){previewProjects=await(await api('/writing-projects')).json();$('#previewLibrary').innerHTML=previewProjects.map((p,i)=>`<button class="review-card" data-project="${i}"><div class="review-card-top"><span class="folder-icon">▱</span><span class="pill">${esc(workflowNames[p.status]||p.status)}</span></div><h3>${esc(p.title)}</h3><p class="fine">${esc(p.client||'Identificação pendente')}</p><p class="fine">${esc(p.research_title)} · ${p.source_count} fontes</p><div class="review-card-bottom"><span>${p.saved_at?stamp(p.saved_at):'Aguardando preparação'}</span><b>↗</b></div></button>`).join('')||'<div class="empty"><h3>Nenhuma prévia inicial</h3><p>Crie uma prévia a partir de uma pesquisa realizada.</p></div>';$$('[data-project]').forEach(b=>b.onclick=()=>action(()=>loadWriting(previewProjects[Number(b.dataset.project)])));}
async function loadWriting(project){if(writingDirty)await saveWriting();stopPolling();rid=project.review_id;writingLoadedRid=rid;draftId=project.draft_id||'';writingData=await(await api(writingPath())).json();snapshot=await(await api('/reviews/'+rid)).json();ensureRich();writingDirty=false;writingResponseId='';writingProposal=null;$('#applyAi').hidden=true;$('#aiReply').textContent='';const d=writingData.draft;for(const [id,key]of [['draftTitle','title'],['draftTheme','theme'],['draftClient','client'],['draftInstructions','instructions'],['draftProduction','production_text'],['templateText','template_text']])$('#'+id).value=d[key]||'';templateDocx=d.template_docx||'';templateFilename=d.template_name||'';$('#templateName').textContent=templateFilename||'Nenhum modelo enviado. Use {{nome}}, {{titulo}}, {{cidade}}, {{redator}}, {{banca}}, {{instituicao}}, {{curso}}, {{ano}} no modelo.';$$('[data-identity]').forEach(e=>e.value=d.identity?.[e.dataset.identity]||'');$$('[data-layout]').forEach(e=>{e.value=d.layout?.[e.dataset.layout]??({font:'Arial',pages:10,size:12,spacing:1.5,top:3,bottom:2,left:3,right:2}[e.dataset.layout]);});richEditor.commands.setContent(d.rich?.type?d.rich:plainRich(d.content),{emitUpdate:false});$('#draftContent').value=d.content||'';$('#writingWorkspace').hidden=false;$('#projectResearch').textContent='Pesquisa: '+snapshot.review.title;$('#editorProjectName').textContent=d.title;show('preview');renderWritingMeta();renderWritingActivity();renderCitations();checkWritingResponse();if(hasActive(snapshot))startPolling();}
function draftBody(){const identity={},layout={};$$('[data-identity]').forEach(e=>identity[e.dataset.identity]=e.value);$$('[data-layout]').forEach(e=>layout[e.dataset.layout]=e.dataset.layout==='font'?e.value:Number(e.value));return {revision:writingData?.revision||'',title:$('#draftTitle').value,theme:$('#draftTheme').value,client:$('#draftClient').value,instructions:$('#draftInstructions').value,production_text:$('#draftProduction').value,content:richEditor?richEditor.getText({blockSeparator:'\n'}):'',rich:richEditor?.getJSON()||{},identity,layout,template_text:$('#templateText').value,template_name:templateFilename,template_docx:templateDocx};}
async function saveWriting(){if(!writingLoadedRid)return;if(!writingDirty&&writingData?.revision)return;writingData=await(await api(writingPath(),{method:'PUT',body:JSON.stringify(draftBody())})).json();writingDirty=false;renderWritingMeta();}
function renderWritingMeta(){if(!writingData)return;$('#draftSaveStatus').textContent=writingDirty?'Alterações não salvas':writingData.saved_at?'Salvo · '+stamp(writingData.saved_at):'Ainda sem versão salva';$('#workflowStatus').textContent=workflowNames[writingData.workflow.status]||'Em preparação';$('#startFinal').disabled=writingData.workflow.status!=='approved';const locked=['approved','final_started'].includes(writingData.workflow.status);richEditor?.setEditable(!locked);$('#writingSources').innerHTML=`<p class="fine">${writingData.sources.length} artigos vinculados · fontes com título/resumo indicadas como preliminares.</p>`+writingData.sources.map(s=>`<button class="source-note text-button" data-source="${esc(s.pmid)}">${esc(s.title)}<br>PMID ${esc(s.pmid)} · ${s.full_text_reviewed?'Texto completo avaliado':'Fonte preliminar'}</button>`).join('');$('#writingComments').innerHTML=writingData.comments.filter(c=>!c.resolved).map(c=>`<div class="comment-note">${c.anchor?`<blockquote>${esc(c.anchor)}</blockquote>`:''}<p>${esc(c.text)}</p><button class="text-button" data-comment-go="${c.id}">Localizar trecho</button> · <button class="text-button" data-resolve-comment="${c.id}">Resolver</button></div>`).join('');$$('[data-resolve-comment]').forEach(b=>b.onclick=()=>action(async()=>{writingData=await(await api(writingPath(`/comments/${b.dataset.resolveComment}/resolve`),{method:'POST'})).json();renderWritingMeta();},b));$$('[data-comment-go]').forEach(b=>b.onclick=()=>{const c=writingData.comments.find(c=>c.id===b.dataset.commentGo);let found=false;richEditor.state.doc.descendants((n,pos)=>{if(n.isText&&!found){const i=n.text.indexOf(c.anchor);if(c.anchor&&i>=0){richEditor.chain().focus().setTextSelection({from:pos+i,to:pos+i+c.anchor.length}).run();found=true;}}});if(!found)message('O trecho foi alterado; o comentário mantém a citação original.');});$('#writingVersions').innerHTML=writingData.revisions.slice().reverse().map(r=>`<p class="fine">${stamp(r.created_at)} · ${esc(r.id.slice(0,8))}</p>`).join('');bindSources();}
function renderCitations(){if(!richEditor||!writingData)return;const text=richEditor.getText();$('#wordCount').textContent=text.trim().split(/\s+/).filter(Boolean).length+' palavras';let blocks=[];richEditor.state.doc.descendants((n,pos)=>{if(n.isBlock&&n.type.name!=='doc'){const ids=[...n.textContent.matchAll(/PMID:\s*(\d+)/gi)].map(m=>m[1]);if(ids.length)blocks.push(`<div class="paragraph-source"><span>${esc(n.textContent.slice(0,95))}…</span>${[...new Set(ids)].map(id=>`<button data-source="${esc(id)}">PMID ${esc(id)} ↗</button>`).join('')}</div>`);}});$('#paragraphSources').innerHTML='<h3>Fontes por trecho</h3><p class="fine">Vínculos por citação PMID. Indicam a referência declarada; não certificam que cada afirmação foi validada no texto completo.</p>'+blocks.join('');bindSources();}
function bindSources(){$$('[data-source]').forEach(b=>b.onclick=()=>openSource(b.dataset.source));}
function openSource(pmid){const s=writingData.sources.find(s=>String(s.pmid)===String(pmid));if(!s){message('Esta referência não está entre os artigos aceitos.',true);return;}$('#sourceDialogBody').innerHTML=`<span class="eyebrow">FONTE DO TRECHO</span><h2>${esc(s.title)}</h2><p>${s.full_text_reviewed?'Texto completo avaliado':'Fonte preliminar · resumo'}</p><p>${esc(s.abstract||'Resumo não disponível')}</p><a class="button secondary" href="https://pubmed.ncbi.nlm.nih.gov/${encodeURIComponent(s.pmid)}/" target="_blank" rel="noopener noreferrer">Abrir artigo no PubMed ↗</a>${s.pdf_status==='available'?`<button class="button primary" id="sourcePdf">Abrir PDF</button>`:''}`;$('#sourceDialog').showModal();if($('#sourcePdf'))$('#sourcePdf').onclick=()=>action(()=>download(`/reviews/${writingLoadedRid}/articles/${s.id}/pdf`,'artigo.pdf',true));}
function renderWritingActivity(){const j=snapshot?.jobs.filter(j=>j.kind==='writing'&&(j.payload.draft_id||'')===draftId).sort((a,b)=>b.created_at-a.created_at)[0];$('#writingActivity').innerHTML=j?`${['pending','running'].includes(j.status)?'<i class="spinner"></i>':''}<span>${j.status==='done'?'Assistência concluída · proposta disponível':j.status==='pending'||j.status==='running'?'Preparando a prévia…':esc(j.status)}</span><button id="writingHistory">Ver Histórico →</button>`:'';if($('#writingHistory'))$('#writingHistory').onclick=()=>action(async()=>{await loadReview(writingLoadedRid);setTab('history');});}
function checkWritingResponse(){const j=snapshot?.jobs.filter(j=>j.kind==='writing'&&(j.payload.draft_id||'')===draftId&&j.payload.result&&j.status==='done').sort((a,b)=>b.created_at-a.created_at)[0];if(!j||j.id===writingResponseId)return;writingResponseId=j.id;writingProposal=j;const r=j.payload.result;$('#aiReply').innerHTML=`<div class="ai-answer">${esc(r.content)}</div>${r.cautions?.length?`<div class="ai-cautions">${r.cautions.map(esc).join('<br>')}</div>`:''}`;$('#applyAi').hidden=j.payload.mode==='question';$('#aiPanel').hidden=false;}
async function askWriting(mode,instruction=''){rid=writingLoadedRid;if(!writingLoadedRid)throw Error('Abra uma prévia para conversar sobre o trabalho.');await saveWriting();await api(writingPath('/assist'),{method:'POST',body:JSON.stringify({mode,instruction})});$('#aiReply').textContent='Preparando resposta. Você será notificado quando terminar; acompanhe ou cancele no Histórico.';$('#applyAi').hidden=true;$('#aiPanel').hidden=false;await pollReview();startPolling();}
$('#newPreview').onclick=async()=>{if(writingDirty)await saveWriting();await list();$('#newPreviewResearch').innerHTML=reviews.filter(r=>r.approved_at).map(r=>`<option value="${esc(r.id)}">${esc(r.title)}</option>`).join('');$('#newPreviewTitle').value='';$('#newPreviewDialog').showModal();};$('#closeNewPreview').onclick=()=>$('#newPreviewDialog').close();$('#newPreviewForm').onsubmit=e=>{e.preventDefault();action(async()=>{const p=await(await api(`/reviews/${$('#newPreviewResearch').value}/writing-projects`,{method:'POST',body:JSON.stringify({title:$('#newPreviewTitle').value})})).json();$('#newPreviewDialog').close();await loadWriting(p);},e.submitter);};
for(const id of ['draftTitle','draftTheme','draftClient','draftInstructions','draftProduction','templateText'])$('#'+id).oninput=()=>writingDirty=true;$$('[data-layout],[data-identity]').forEach(e=>e.oninput=()=>writingDirty=true);
for(const id of ['saveWriting','saveWord'])$('#'+id).onclick=e=>action(saveWriting,e.currentTarget);
for(const id of ['exportWriting','exportWord'])$('#'+id).onclick=e=>action(async()=>{await saveWriting();await download(writingPath('/docx'),'previa-inicial.docx');},e.currentTarget);
$('#generateWriting').onclick=e=>action(()=>askWriting('draft'),e.currentTarget);$('#openWord').onclick=()=>{if(!writingLoadedRid)return;show('word');};$('#backPreview').onclick=()=>show('preview');$('#writingResearch').onclick=()=>action(()=>loadReview(rid));$('#startWriting').onclick=()=>show('pre');
$('#draftFile').onchange=e=>action(async()=>{const f=e.target.files[0];if(!f)return;const d=await(await api('/documents/extract',{method:'POST',raw:true,headers:{'X-Filename':encodeURIComponent(f.name),'Content-Type':'application/octet-stream'},body:f})).json();$('#draftProduction').value=d.text;writingDirty=true;await saveWriting();message('Ficha incorporada.');});
$('#templateFile').onchange=e=>action(async()=>{const f=e.target.files[0];if(!f)return;if(f.size>4*1024*1024)throw Error('Modelo deve ter até 4 MB.');const d=await(await api(writingPath('/template'),{method:'POST',raw:true,headers:{'Content-Type':'application/octet-stream'},body:f})).json();templateDocx=d.template_docx;templateFilename=f.name;$('#templateText').value=d.template_text;$('#templateName').textContent=f.name;writingDirty=true;await saveWriting();message('Modelo pré-textual salvo. Seu conteúdo será preservado no Word.');});
$('#addComment').onclick=e=>action(async()=>{const text=$('#commentText').value.trim();if(!text)throw Error('Escreva um comentário, elogio ou ajuste.');if(commentSelection)richEditor.chain().setMark('commentAnchor',{id:crypto.randomUUID()}).run();await saveWriting();writingData=await(await api(writingPath('/comments'),{method:'POST',body:JSON.stringify({text,anchor:commentSelection})})).json();$('#commentText').value='';renderWritingMeta();},e.currentTarget);
$('#aiToggle').onclick=()=>{if(!writingLoadedRid){show('pre');message('Abra uma prévia para conversar sobre o trabalho.');return;}$('#aiPanel').hidden=!$('#aiPanel').hidden;};$('#closeAi').onclick=()=>$('#aiPanel').hidden=true;$('#askAi').onclick=e=>action(()=>askWriting($('#aiMode').value,$('#aiInstruction').value+(commentSelection?'\nTrecho: '+commentSelection:'')),e.currentTarget);
$('#applyAi').onclick=e=>action(async()=>{if(!writingProposal)return;if(writingDirty)throw Error('Salve suas alterações primeiro.');if(writingProposal.payload.context.revision!==writingData.revision)throw Error('Proposta de uma versão anterior. Solicite nova correção.');richEditor.commands.setContent(plainRich(writingProposal.payload.result.content));writingDirty=true;await saveWriting();$('#applyAi').hidden=true;show('word');message('Proposta aplicada. Revise o documento e os vínculos às fontes.');},e.currentTarget);
async function transition(status){if(status!=='changes_requested')await saveWriting();writingData=await(await api(writingPath('/workflow'),{method:'POST',body:JSON.stringify({status,note:$('#workflowNote').value})})).json();renderWritingMeta();message(workflowNames[status]);if(status==='final_started'){show('full');$('#fullView').innerHTML=`<h1>Versão final</h1><div class="glass panel"><h2>${esc(writingData.draft.title)}</h2><p>Iniciada a partir da prévia aprovada. A versão aprovada foi registrada no histórico para orientar a produção final.</p><button class="button secondary" id="returnApproved">Abrir prévia aprovada</button></div>`;$('#returnApproved').onclick=()=>show('preview');}}
$('#requestChanges').onclick=e=>action(()=>transition('changes_requested'),e.currentTarget);$('#approvePreview').onclick=e=>action(()=>transition('approved'),e.currentTarget);$('#startFinal').onclick=e=>action(()=>transition('final_started'),e.currentTarget);$('#reviewReady').onclick=e=>action(()=>transition('ready_for_review'),e.currentTarget);
async function refreshNotifications(){notifications=await(await api('/notifications')).json();$('#notificationCount').textContent=notifications.filter(n=>!n.read).length;$('#notificationsList').innerHTML=notifications.map((n,i)=>`<button class="notification-item ${n.read?'read':''}" data-notification="${i}"><strong>${esc(n.message)}</strong><span>${esc(n.title)}</span><small>${stamp(n.created_at)} · ${n.read?'Lida':'Nova'}</small></button>`).join('')||'<p>Nenhuma notificação.</p>';$$('[data-notification]').forEach(b=>b.onclick=()=>action(async()=>{const n=notifications[Number(b.dataset.notification)];await api(`/reviews/${n.review_id}/notifications/${n.id}/read`,{method:'POST'});$('#notificationsDialog').close();await loadWriting(n);await refreshNotifications();}));}
$('#notificationBell').onclick=()=>action(async()=>{await refreshNotifications();$('#notificationsDialog').showModal();});$('#closeNotifications').onclick=()=>$('#notificationsDialog').close();$('#closeSource').onclick=()=>$('#sourceDialog').close();window.addEventListener('beforeunload',e=>{if(writingDirty){e.preventDefault();e.returnValue='';}});fetch('/health/ready').then(r=>$('#systemStatus').textContent=r.ok?'● Sistema online':'● Sistema em ajustes').catch(()=>$('#systemStatus').textContent='● Sistema indisponível');

window.addEventListener('studio-source',e=>openSource(e.detail));

$('#fixPreview').onclick=e=>action(()=>askWriting('revision',$('#workflowNote').value||writingData.workflow.note||'Revise os comentários e proponha os ajustes necessários.'),e.currentTarget);

async function loadFinalLibrary(){const projects=await(await api('/writing-projects')).json();const finals=projects.filter(p=>p.status==='final_started');$('#fullView').innerHTML='<h1>Versão final</h1><p class="muted">Trabalhos iniciados a partir de uma prévia aprovada.</p><div class="review-grid">'+finals.map((p,i)=>`<button class="review-card" data-final="${i}"><span class="pill">Versão final iniciada</span><h3>${esc(p.title)}</h3><p>Prévia aprovada registrada no histórico</p></button>`).join('')+'</div>'+(!finals.length?'<div class="glass panel"><p>Aprove uma prévia e use Iniciar versão final para registrar o próximo passo.</p></div>':'');$$('[data-final]').forEach(b=>b.onclick=()=>action(()=>loadWriting(finals[Number(b.dataset.final)])));}
